package slayertaskodds;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarbitID;

final class BlockSync
{
    static final int SLOT_COUNT = 7;
    private static final Map<SlayerMaster, int[]> VARBITS = new EnumMap<>(SlayerMaster.class);
    static
    {
        VARBITS.put(SlayerMaster.TURAEL, new int[] {VarbitID.SLAYER_BLOCKED_TURAEL_1, VarbitID.SLAYER_BLOCKED_TURAEL_2, VarbitID.SLAYER_BLOCKED_TURAEL_3, VarbitID.SLAYER_BLOCKED_TURAEL_4, VarbitID.SLAYER_BLOCKED_TURAEL_5, VarbitID.SLAYER_BLOCKED_TURAEL_6, VarbitID.SLAYER_BLOCKED_TURAEL_DIARY});
        VARBITS.put(SlayerMaster.KRYSTILIA, new int[] {VarbitID.SLAYER_BLOCKED_KRYSTILIA_1, VarbitID.SLAYER_BLOCKED_KRYSTILIA_2, VarbitID.SLAYER_BLOCKED_KRYSTILIA_3, VarbitID.SLAYER_BLOCKED_KRYSTILIA_4, VarbitID.SLAYER_BLOCKED_KRYSTILIA_5, VarbitID.SLAYER_BLOCKED_KRYSTILIA_6, VarbitID.SLAYER_BLOCKED_KRYSTILIA_DIARY});
        VARBITS.put(SlayerMaster.MAZCHNA, new int[] {VarbitID.SLAYER_BLOCKED_MAZCHNA_1, VarbitID.SLAYER_BLOCKED_MAZCHNA_2, VarbitID.SLAYER_BLOCKED_MAZCHNA_3, VarbitID.SLAYER_BLOCKED_MAZCHNA_4, VarbitID.SLAYER_BLOCKED_MAZCHNA_5, VarbitID.SLAYER_BLOCKED_MAZCHNA_6, VarbitID.SLAYER_BLOCKED_MAZCHNA_DIARY});
        VARBITS.put(SlayerMaster.VANNAKA, new int[] {VarbitID.SLAYER_BLOCKED_VANNAKA_1, VarbitID.SLAYER_BLOCKED_VANNAKA_2, VarbitID.SLAYER_BLOCKED_VANNAKA_3, VarbitID.SLAYER_BLOCKED_VANNAKA_4, VarbitID.SLAYER_BLOCKED_VANNAKA_5, VarbitID.SLAYER_BLOCKED_VANNAKA_6, VarbitID.SLAYER_BLOCKED_VANNAKA_DIARY});
        VARBITS.put(SlayerMaster.CHAELDAR, new int[] {VarbitID.SLAYER_BLOCKED_CHAELDAR_1, VarbitID.SLAYER_BLOCKED_CHAELDAR_2, VarbitID.SLAYER_BLOCKED_CHAELDAR_3, VarbitID.SLAYER_BLOCKED_CHAELDAR_4, VarbitID.SLAYER_BLOCKED_CHAELDAR_5, VarbitID.SLAYER_BLOCKED_CHAELDAR_6, VarbitID.SLAYER_BLOCKED_CHAELDAR_DIARY});
        VARBITS.put(SlayerMaster.KONAR, new int[] {VarbitID.SLAYER_BLOCKED_KONAR_1, VarbitID.SLAYER_BLOCKED_KONAR_2, VarbitID.SLAYER_BLOCKED_KONAR_3, VarbitID.SLAYER_BLOCKED_KONAR_4, VarbitID.SLAYER_BLOCKED_KONAR_5, VarbitID.SLAYER_BLOCKED_KONAR_6, VarbitID.SLAYER_BLOCKED_KONAR_DIARY});
        VARBITS.put(SlayerMaster.NIEVE, new int[] {VarbitID.SLAYER_BLOCKED_NIEVE_1, VarbitID.SLAYER_BLOCKED_NIEVE_2, VarbitID.SLAYER_BLOCKED_NIEVE_3, VarbitID.SLAYER_BLOCKED_NIEVE_4, VarbitID.SLAYER_BLOCKED_NIEVE_5, VarbitID.SLAYER_BLOCKED_NIEVE_6, VarbitID.SLAYER_BLOCKED_NIEVE_DIARY});
        VARBITS.put(SlayerMaster.DURADEL, new int[] {VarbitID.SLAYER_BLOCKED_DURADEL_1, VarbitID.SLAYER_BLOCKED_DURADEL_2, VarbitID.SLAYER_BLOCKED_DURADEL_3, VarbitID.SLAYER_BLOCKED_DURADEL_4, VarbitID.SLAYER_BLOCKED_DURADEL_5, VarbitID.SLAYER_BLOCKED_DURADEL_6, VarbitID.SLAYER_BLOCKED_DURADEL_DIARY});
    }

    static List<SlayerTaskChoice> read(Client client, SlayerMaster master)
    {
        List<SlayerTaskChoice> slots = new ArrayList<>();
        for (int varbit : VARBITS.get(master))
        {
            int taskId = client.getVarbitValue(varbit);
            if (taskId == 0) { slots.add(SlayerTaskChoice.NONE); continue; }
            List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, taskId);
            if (rows == null || rows.isEmpty()) throw new IllegalStateException("Unknown blocked task ID " + taskId);
            Object[] names = client.getDBTableField(rows.get(0), DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0);
            if (names == null || names.length == 0) throw new IllegalStateException("Task names are not ready");
            SlayerTaskChoice choice = SlayerTaskChoice.fromStoredValue(String.valueOf(names[0]));
            if (choice == null) throw new IllegalStateException("Unsupported blocked task: " + names[0]);
            slots.add(choice);
        }
        return slots;
    }
}

package slayertaskodds;

import java.io.IOException;
import java.io.InputStream;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Properties;
import javax.imageio.ImageIO;
import javax.swing.ImageIcon;

/** Small, bundled Wiki portraits. Accessed only on the Swing event thread. */
final class MonsterImages
{
    private final Properties catalog = new Properties();
    private final Map<String, ImageIcon> cache = new HashMap<>();
    private final ImageIcon fallback;

    MonsterImages()
    {
        fallback = read("/slayertaskodds/icon.png");
        try (InputStream stream = MonsterImages.class.getResourceAsStream("/slayertaskodds/monsters/catalog.properties"))
        {
            if (stream != null) catalog.load(stream);
        }
        catch (IOException ignored)
        {
            // A missing portrait must never prevent the calculator from opening.
        }
    }

    ImageIcon forTask(String task)
    {
        if (task == null) return fallback;
        String key = task.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]", "");
        if (cache.containsKey(key)) return cache.get(key);
        String file = catalog.getProperty(key);
        ImageIcon image = file == null ? null : read("/slayertaskodds/monsters/" + file);
        if (image == null) image = fallback;
        cache.put(key, image);
        return image;
    }

    private static ImageIcon read(String path)
    {
        try (InputStream stream = MonsterImages.class.getResourceAsStream(path))
        {
            if (stream == null) return null;
            java.awt.image.BufferedImage image = ImageIO.read(stream);
            return image == null ? null : new ImageIcon(image);
        }
        catch (IOException ex) { return null; }
    }
}

package slayertaskodds;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

final class PlayerState
{
    final Map<String, Boolean> checks = new HashMap<>();
    final Map<String, Integer> stats = new HashMap<>();
    final Set<String> quests = new HashSet<>();
    final Set<String> unlocks = new HashSet<>();
    final Set<String> other = new HashSet<>();
    String currentTask;
    boolean slayerCapePerkActive;

    boolean isCurrentTask(String taskName)
    {
        return currentTask != null
            && SlayerTaskChoice.identity(currentTask).equals(SlayerTaskChoice.identity(taskName));
    }

    boolean eligible(SlayerTask task)
    {
        for (Map.Entry<String, Integer> requirement : task.stats.entrySet())
            if (stats.getOrDefault(requirement.getKey(), 0) < requirement.getValue()) return false;
        if (!quests.containsAll(task.quests)) return false;
        if (task.other != null && !other.contains(task.other)) return false;
        if ("Stop the Wyvern".equals(task.unlock)) return !unlocks.contains(task.unlock);
        return task.unlock == null || unlocks.contains(task.unlock);
    }

    int weight(SlayerTask task)
    {
        return task.bonusUnlock != null && unlocks.contains(task.bonusUnlock) ? task.bonusWeight : task.weight;
    }
}

package slayertaskodds;

import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ItemID;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.config.ConfigManager;

final class PlayerStateReader
{
    private static final Map<String, Integer> UNLOCKS = new HashMap<>();
    static
    {
        UNLOCKS.put("Seeing red", VarbitID.SLAYER_UNLOCK_REDDRAGONS);
        UNLOCKS.put("I hope you mith me", VarbitID.SLAYER_UNLOCK_MITHRILDRAGONS);
        UNLOCKS.put("Watch the birdie", VarbitID.SLAYER_UNLOCK_AVIANSIES);
        UNLOCKS.put("Hot stuff", VarbitID.SLAYER_UNLOCK_TZHAAR);
        UNLOCKS.put("Reptile got ripped", VarbitID.SLAYER_UNLOCK_LIZARDMEN);
        UNLOCKS.put("Like a boss", VarbitID.SLAYER_UNLOCK_BOSSES);
        UNLOCKS.put("Stop the Wyvern", VarbitID.SLAYER_UNLOCK_FOSSILWYVERNBLOCK);
        UNLOCKS.put("Basilocked", VarbitID.SLAYER_UNLOCK_BASILISK);
        UNLOCKS.put("Unlock vampyres", VarbitID.SLAYER_UNLOCK_VAMPYRES);
        UNLOCKS.put("I Wildy More Slayer", VarbitID.SLAYER_UNLOCK_WILDY_EXTRATASKS);
        UNLOCKS.put("Warped Reality", VarbitID.SLAYER_UNLOCK_WARPED_CREATURES);
        UNLOCKS.put("Wings Spread", VarbitID.SLAYER_UNLOCK_GRYPHONS);
        UNLOCKS.put("Lured In", VarbitID.SLAYER_UNLOCK_AQUANITES);
        UNLOCKS.put("Chance of Heavy Frost", VarbitID.SLAYER_WEIGHTED_LONGER_FROST_DRAGONS);
    }

    static PlayerState read(Client client, ConfigManager configManager, Map<SlayerMaster, List<SlayerTask>> tables)
    {
        PlayerState state = new PlayerState();
        state.currentTask = currentTask(client);
        state.slayerCapePerkActive = containsSlayerCape(client.getItemContainer(InventoryID.INVENTORY))
            || containsSlayerCape(client.getItemContainer(InventoryID.EQUIPMENT));
        for (Skill skill : Skill.values())
            if (skill != Skill.OVERALL) state.stats.put(skill.getName(), client.getRealSkillLevel(skill));
        state.stats.put("Combat", client.getLocalPlayer().getCombatLevel());
        Set<String> requiredQuests = new HashSet<>();
        for (List<SlayerTask> tasks : tables.values()) collectQuests(tasks, requiredQuests);
        for (String name : requiredQuests)
        {
            Quest quest = quest(name);
            QuestState progress = quest.getState(client);
            boolean started = name.equals("Dragon Slayer") || name.equals("Desert Treasure");
            if (progress == QuestState.FINISHED || started && progress == QuestState.IN_PROGRESS)
                state.quests.add(name);
        }
        UNLOCKS.forEach((name, varbit) -> {
            if (client.getVarbitValue(varbit) > 0) state.unlocks.add(name);
        });
        if (client.getVarbitValue(VarbitID.SLAYER_TOGGLEOFF_FOSSILWYVERNBLOCK) > 0)
            state.unlocks.remove("Stop the Wyvern");
        if (client.getVarbitValue(VarbitID.BRUT_CRAFT_SHIP) >= 1)
            state.other.add("Ancient Cavern");
        if (state.stats.getOrDefault("Strength", 0) >= 60 || state.stats.getOrDefault("Agility", 0) >= 60)
            state.other.add("Access GWD");
        // Remember a key observed in inventory/bank for this RS account, even if later banked.
        boolean keyKnown = client.getVarbitValue(VarbitID.GARGBOSS_UNLOCKED_ROOF) > 0
            || containsKey(client.getItemContainer(InventoryID.INVENTORY))
            || containsKey(client.getItemContainer(InventoryID.BANK));
        boolean keyRemembered = Boolean.TRUE.equals(configManager.getRSProfileConfiguration(SlayerOddsConfig.GROUP, "brittleKeySeen", boolean.class));
        if (keyKnown && !keyRemembered) configManager.setRSProfileConfiguration(SlayerOddsConfig.GROUP, "brittleKeySeen", true);
        if (keyKnown || keyRemembered)
            state.other.add("Brittle Key");
        if (Quest.ENTER_THE_ABYSS.getState(client) == QuestState.FINISHED) state.other.add("Access Abyss");
        for (String name : requiredQuests) state.checks.put(name + (name.equals("Dragon Slayer") || name.equals("Desert Treasure") ? " started" : " completed"), state.quests.contains(name));
        for (String name : UNLOCKS.keySet()) state.checks.put(name, state.unlocks.contains(name));
        for (String name : new String[] {"Ancient Cavern", "Access GWD", "Brittle Key", "Access Abyss"})
            state.checks.put(name, state.other.contains(name));
        state.checks.put("Thieving at least 23", state.stats.getOrDefault("Thieving", 0) >= 23);
        state.checks.put("Firemaking at least 33", state.stats.getOrDefault("Firemaking", 0) >= 33);
        state.checks.put("Magic at least 50", state.stats.getOrDefault("Magic", 0) >= 50);
        return state;
    }

    private static String currentTask(Client client)
    {
        // Keep reading SLAYER_TARGET when SLAYER_COUNT reaches zero: the game
        // still treats the completed assignment as current until another task is assigned.
        int taskId = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
        if (taskId <= 0) return null;

        // The game uses task ID 98 for the grouped Bosses assignment.
        if (taskId == 98) return "Bosses";

        List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerTask.ID,
            DBTableID.SlayerTask.COL_ID, 0, taskId);
        if (rows == null || rows.isEmpty()) return null;
        Object[] names = client.getDBTableField(rows.get(0), DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0);
        return names == null || names.length == 0 ? null : String.valueOf(names[0]);
    }

    private static boolean containsKey(ItemContainer container)
    {
        if (container == null) return false;
        for (Item item : container.getItems()) if (item.getId() == ItemID.BRITTLE_KEY) return true;
        return false;
    }

    private static boolean containsSlayerCape(ItemContainer container)
    {
        if (container == null) return false;
        for (Item item : container.getItems())
            if (item.getId() == ItemID.SLAYER_CAPE || item.getId() == ItemID.SLAYER_CAPET) return true;
        return false;
    }

    private static void collectQuests(List<SlayerTask> tasks, Set<String> quests)
    {
        for (SlayerTask task : tasks)
        {
            quests.addAll(task.quests);
            if (task.subtasks != null) collectQuests(task.subtasks, quests);
        }
    }

    static Quest quest(String name)
    {
        switch (name)
        {
            case "Dragon Slayer": return Quest.DRAGON_SLAYER_I;
            case "Desert Treasure": return Quest.DESERT_TREASURE_I;
            case "Desert Treasure 2": return Quest.DESERT_TREASURE_II__THE_FALLEN_EMPIRE;
            default: return Quest.valueOf(name.toUpperCase(Locale.ROOT).replace("!", "").replace(' ', '_'));
        }
    }
}

package slayertaskodds;

import net.runelite.api.coords.WorldPoint;

enum SlayerMaster
{
	// Destinations checked against Slayer Simplified's SlayerMaster locations.
	// https://github.com/Wulfic/slayer-simplified/blob/master/src/main/java/com/slayersimplified/domain/SlayerMaster.java
	TURAEL("Turael / Aya", "turael", 2931, 3536),
	KRYSTILIA("Krystilia", "krystilia", 3109, 3514),
	MAZCHNA("Mazchna / Achtryn", "mazchna", 3510, 3507),
	VANNAKA("Vannaka", "vannaka", 3145, 9914),
	CHAELDAR("Chaeldar", "chaeldar", 2445, 4431),
	KONAR("Konar quo Maten", "konar", 1308, 3786),
	NIEVE("Nieve / Steve", "nieve", 2432, 3424),
	DURADEL("Duradel / Kuradal", "duradel", 2869, 2982);

	final String displayName;
	final String key;
	final WorldPoint destination;

	SlayerMaster(String displayName, String key, int x, int y)
	{
		this.displayName = displayName;
		this.key = key;
		this.destination = new WorldPoint(x, y, 0);
	}

	static SlayerMaster byGameId(int id)
    {
        switch (id)
        {
            case 1: return TURAEL;
            case 2: return MAZCHNA;
            case 3: return VANNAKA;
            case 4: return CHAELDAR;
            case 5: return DURADEL;
            case 6: return NIEVE;
            case 7: return KRYSTILIA;
            case 8: return KONAR;
            default: return null;
        }
    }

    static SlayerMaster byKey(String key)
	{
		for (SlayerMaster master : values())
		{
			if (master.key.equals(key)) return master;
		}
		return null;
	}
}

package slayertaskodds;

import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Set;

final class SlayerOdds
{
    private SlayerOdds() { }

    static Result calculate(Iterable<SlayerTask> tasks, String monster, Set<String> blocked, PlayerState state)
    {
        Result weighted = calculateWeighted(tasks, monster, blocked, state);
        if (!state.slayerCapePerkActive || state.currentTask == null
            || !isAvailable(tasks, state.currentTask, blocked, state))
            return weighted;

        if (state.isCurrentTask(monster))
            return new Result(weighted.targetWeight, weighted.totalWeight, weighted.count, 0.10,
                "10% Slayer cape repeat", "The Slayer cape gives a 10% chance to repeat your previous task.");

        return new Result(weighted.targetWeight, weighted.totalWeight, weighted.count,
            weighted.chance() * 0.90, weighted.formula() + " x 90%",
            "The Slayer cape reserves 10% for repeating your previous task; this is the normal weighted chance.");
    }

    private static Result calculateWeighted(Iterable<SlayerTask> tasks, String monster,
        Set<String> blocked, PlayerState state)
    {
        int total = 0, target = 0, count = 0;
        for (SlayerTask task : tasks)
        {
            if (blocked.contains(SlayerTaskChoice.identity(task.name)) || state.isCurrentTask(task.name)
                || !state.eligible(task)) continue;
            int weight = state.weight(task);
            total += weight;
            count++;
            if (SlayerTaskChoice.identity(task.name).equals(SlayerTaskChoice.identity(monster))) target += weight;
        }
        double probability = total == 0 ? 0 : (double) target / total;
        String formula = target + " / " + total + " weight";
        for (SlayerTask task : tasks)
        {
            if (task.subtasks == null || !state.eligible(task) || state.isCurrentTask(task.name)
                || blocked.contains(SlayerTaskChoice.identity(task.name))) continue;
            Result sub = calculateWeighted(task.subtasks, monster, blocked, state);
            if (total > 0 && sub.chance() > 0)
            {
                probability += (double) state.weight(task) / total * sub.chance();
                formula = state.weight(task) + " / " + total + " x " + sub.formula();
            }
        }
        String explanation = probability == 0
            ? unavailableReason(tasks, monster, blocked, state)
            : probability * 100.0 < 0.005
                ? "This task is available, but its chance is below 0.005% and rounds to 0.00%."
                : "This task is available from this master.";
        return new Result(target, total, count, probability, formula, explanation);
    }

    private static boolean isAvailable(Iterable<SlayerTask> tasks, String monster,
        Set<String> blocked, PlayerState state)
    {
        return isAvailable(tasks, monster, blocked, state, false, true);
    }

    private static boolean isAvailable(Iterable<SlayerTask> tasks, String monster,
        Set<String> blocked, PlayerState state, boolean blockedParent, boolean eligibleParent)
    {
        for (SlayerTask task : tasks)
        {
            boolean blockedHere = blockedParent || blocked.contains(SlayerTaskChoice.identity(task.name));
            boolean eligibleHere = eligibleParent && state.eligible(task);
            if (SlayerTaskChoice.identity(task.name).equals(SlayerTaskChoice.identity(monster)))
                return !blockedHere && eligibleHere;
            if (task.subtasks != null && isAvailable(task.subtasks, monster, blocked, state,
                blockedHere, eligibleHere))
                return true;
        }
        return false;
    }

    private static String unavailableReason(Iterable<SlayerTask> tasks, String monster,
        Set<String> blocked, PlayerState state)
    {
        if (state.isCurrentTask(monster))
            return "Your current task cannot be assigned again until you receive a different task.";
        Availability availability = new Availability();
        inspect(tasks, monster, blocked, state, new ArrayList<>(), false, availability);
        if (!availability.found) return "This master never assigns this task.";
        if (!availability.unblocked) return "Blocked in this master's saved block list.";
        if (!availability.missingRequirements.isEmpty())
        {
            List<String> missing = new ArrayList<>(availability.missingRequirements);
            Collections.sort(missing, String.CASE_INSENSITIVE_ORDER);
            return "Requirements not met: " + String.join(", ", missing) + ".";
        }
        return "This task has no eligible weight for this master and account.";
    }

    private static void inspect(Iterable<SlayerTask> tasks, String monster, Set<String> blocked,
        PlayerState state, List<SlayerTask> parents, boolean blockedParent, Availability result)
    {
        for (SlayerTask task : tasks)
        {
            boolean blockedHere = blockedParent || blocked.contains(SlayerTaskChoice.identity(task.name));
            parents.add(task);
            if (SlayerTaskChoice.identity(task.name).equals(SlayerTaskChoice.identity(monster)))
            {
                result.found = true;
                if (!blockedHere)
                {
                    result.unblocked = true;
                    for (SlayerTask requirement : parents) collectMissing(requirement, state, result.missingRequirements);
                }
            }
            if (task.subtasks != null)
                inspect(task.subtasks, monster, blocked, state, parents, blockedHere, result);
            parents.remove(parents.size() - 1);
        }
    }

    private static void collectMissing(SlayerTask task, PlayerState state, Set<String> missing)
    {
        task.stats.forEach((skill, required) -> {
            int actual = state.stats.getOrDefault(skill, 0);
            if (actual < required) missing.add(skill + " level " + required + " (you have " + actual + ")");
        });
        for (String quest : task.quests)
            if (!state.quests.contains(quest)) missing.add("quest: " + quest);
        boolean hasUnlock = task.unlock != null && state.unlocks.contains(task.unlock);
        if (task.unlock != null && ("Stop the Wyvern".equals(task.unlock) ? hasUnlock : !hasUnlock))
            missing.add(task.unlock.equals("Stop the Wyvern")
                ? "the Stop the Wyvern toggle must be off" : "unlock: " + task.unlock);
        if (task.other != null && !state.other.contains(task.other)) missing.add(task.other);
    }

    private static final class Availability
    {
        private boolean found;
        private boolean unblocked;
        private final Set<String> missingRequirements = new LinkedHashSet<>();
    }

    static Set<String> blocks(String... values)
    {
        Set<String> result = new HashSet<>();
        for (String value : values)
            if (value != null && SlayerTaskChoice.fromStoredValue(value) != SlayerTaskChoice.NONE)
                result.add(SlayerTaskChoice.identity(value));
        return result;
    }

    static final class Result
    {
        final int targetWeight, totalWeight, count;
        private final double probability;
        private final String formula;
        private final String explanation;
        Result(int targetWeight, int totalWeight, int count, double probability, String formula, String explanation)
        { this.targetWeight = targetWeight; this.totalWeight = totalWeight; this.count = count; this.probability = probability; this.formula = formula; this.explanation = explanation; }
        double chance() { return probability; }
        String formula() { return formula; }
        String explanation() { return explanation; }
    }
}

package slayertaskodds;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(SlayerOddsConfig.GROUP)
public interface SlayerOddsConfig extends Config
{
	String GROUP = "slayerodds";

	@ConfigSection(name = "Notifications", description = "Slayer block list synchronization messages", position = 1, closedByDefault = false)
	String notifications = "notifications";
	@ConfigItem(keyName = "postSyncChatMessages", name = "Post sync messages in chat", description = "Show a chat confirmation and the synced block slots when a Slayer master's block list is synchronized", section = SlayerOddsConfig.notifications, position = 1)
	default boolean postSyncChatMessages() { return true; }
	@ConfigSection(name = "Side panel", description = "Master odds display and explanation tooltips", position = 2, closedByDefault = false)
	String display = "display";
	@ConfigItem(keyName = "hideZeroChanceMasters", name = "Hide 0.00% masters", description = "Hide masters whose displayed chance rounds to 0.00% in the side panel", section = SlayerOddsConfig.display, position = 1)
	default boolean hideZeroChanceMasters() { return false; }
